package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyFindingDiscussionTest {
    @TempDir Path root;
    private static final String DOI="10.5555/synthetic-finding-review";
    private Map<String,Object> revision,catalog;
    private Map<String,Map<String,Object>> evidence;
    private Path request,source;
    @BeforeEach void setup()throws Exception{
        request=root.resolve("revision.yaml");Files.writeString(request,"fixture\n");source=root.resolve("public.txt");Files.writeString(source,"DOI: "+DOI+"\nControlled perturbation reduced the synthetic readout. An independent negative control showed no change. PRIVATE_SOURCE_SENTINEL\n");
        Path inventory=Files.createDirectory(root.resolve("inventory"));String finding=StudyAssistance.json(Map.of("finding_id","f1","hypothesis","H","feature_id","G1","candidate",true,"estimable",true,"observations",List.of(Map.of("primary",true,"operation_type","meta_analysis"))));Files.writeString(inventory.resolve("finding-inventory.jsonl"),finding+"\n");StudyTestSources.seal(inventory,"finding_inventory","inventory","H");
        evidence=Map.of("GLOBAL.finding_inventory",Map.of("operation_type","finding_inventory","state","complete","manifest","inventory/manifest.yaml"),"H.meta_analysis",Map.of("operation_type","meta_analysis","state","complete","key_findings",Map.of("tested_features",1)));
        catalog=Map.of("references",List.of(Map.of("reference_id","ref-one","doi",DOI,"identifiers",List.of("doi:"+DOI),"citation_eligible",true,"excerpt","Controlled perturbation reduced the synthetic readout.","excerpt_status","verified_literal_substring_of_normalized_abstract")),"search_coverage",Map.of("status","bounded_fixture_not_scientific_review"));
        String obs="The synthetic G1 association is retained in the declared cohort.";
        String lit="A controlled source experiment tested the molecular step [[cite:"+DOI+"]].";
        String mechanism="The mechanistic link remains an inference in the synthetic study [[cite:"+DOI+"]].";
        String contrary="A negative experiment constrains that interpretation [[cite:"+DOI+"]].";
        String alternative="A linked-feature explanation remains a hypothesis.";
        String relevance="The inference has research relevance without establishing clinical utility.";
        String next="A proposed matched perturbation would distinguish the explanations.";
        String limitation="The synthetic result and source context still require scientific review.";
        var p=paragraph("main","discussion",String.join(" ",obs,mechanism,relevance,limitation));p.put("discussion_role","principal_finding");var supplement=paragraph("supp","supplementary",String.join(" ",lit,contrary,alternative,next));
        var claims=new ArrayList<Object>();claims.add(claim("obs","main",obs,"observed_result",List.of(),List.of()));claims.add(claim("lit","supp",lit,"literature_result",List.of(),List.of(reading("positive","supports"))));claims.add(claim("mechanism","main",mechanism,"inference",List.of("obs","lit"),List.of(reading("positive","contextualizes"))));claims.add(claim("contrary","supp",contrary,"literature_result",List.of(),List.of(reading("negative","contradicts"))));claims.add(claim("alternative","supp",alternative,"hypothesis",List.of("obs","lit"),List.of()));claims.add(claim("relevance","main",relevance,"inference",List.of("mechanism"),List.of()));var experiment=claim("next","supp",next,"proposed_experiment",List.of("mechanism","alternative"),List.of());experiment.put("experiment",Map.of("comparison","Matched perturbation and control","readout","Prespecified synthetic response","discriminates","Different predictions under the two mechanisms","limitations","A model experiment would not establish clinical effects"));claims.add(experiment);claims.add(claim("limitation","main",limitation,"limitation",List.of(),List.of()));
        var facets=new LinkedHashMap<String,Object>();String[] ids={"obs","lit","mechanism","contrary","alternative","relevance","next","limitation"};for(int i=0;i<ids.length;i++)facets.put(StudyFindingDiscussion.FACETS.get(i),Map.of("status","addressed","claim_ids",List.of(ids[i]),"reason","Synthetic prose explicitly discusses this facet; interpretation remains unapproved"));
        var policy=new LinkedHashMap<String,Object>();policy.put("mode","strict");policy.put("finding_inventory_sha256",FollowupSupport.hash(inventory.resolve("finding-inventory.jsonl")));policy.put("source_texts",List.of(Map.of("id","paper","reference",DOI,"path","public.txt","sha256",FollowupSupport.hash(source),"scope","full_text","public_literature",true,"provenance","Caller-declared synthetic public source, not a real journal article")));policy.put("passages",List.of(Map.of("id","positive","source_text","paper","quote","Controlled perturbation reduced the synthetic readout.","location","Synthetic results"),Map.of("id","negative","source_text","paper","quote","An independent negative control showed no change.","location","Synthetic negative experiment")));policy.put("dossiers",List.of(new LinkedHashMap<>(Map.of("finding_id","f1","paragraph_ids",List.of("main","supp"),"claims",claims,"facets",facets))));revision=new LinkedHashMap<>(Map.of("title","Synthetic finding review","sections",List.of(p,supplement),"finding_review",policy));
    }
    private static Map<String,Object> paragraph(String id,String section,String text){return new LinkedHashMap<>(Map.of("id",id,"section",section,"text",text,"finding_ids",List.of("f1"),"sources",List.of("H.meta_analysis"),"citation_basis","literature"));}
    private static Map<String,Object> reading(String passage,String relationship){return Map.of("passage",passage,"relationship",relationship,"assessment","Attributed support judgment in a synthetic fixture, not scientific certification");}
    private static Map<String,Object> claim(String id,String paragraph,String text,String kind,List<String> dependencies,List<?> readings){var c=new LinkedHashMap<String,Object>();c.put("id",id);c.put("paragraph_id",paragraph);c.put("text",text);c.put("kind",kind);c.put("sources",kind.equals("observed_result")?List.of("H.meta_analysis"):List.of());c.put("depends_on",dependencies);c.put("readings",readings);if(kind.equals("literature_result"))c.put("study_context",Map.of("design","Synthetic controlled model experiment","species","Synthetic system","tissue","Synthetic cell model","molecular_trait","Synthetic molecular readout","phenotype","Synthetic experimental response","limitations","Not a study of patients or real biological effects"));return c;}
    private Map<String,Object> policy(){return StudyPublicEvidence.map(revision.get("finding_review"));}
    private Map<String,Object> dossier(){return StudyPublicEvidence.map(StudyPublicEvidence.list(policy().get("dossiers")).get(0));}
    private void replaceClaim(int index,java.util.function.Consumer<Map<String,Object>> change){var d=dossier();var all=new ArrayList<Object>(StudyPublicEvidence.list(d.get("claims")));var c=new LinkedHashMap<>(StudyPublicEvidence.map(all.get(index)));change.accept(c);all.set(index,c);d.put("claims",all);var p=policy();p.put("dossiers",List.of(d));revision.put("finding_review",p);}
    private StudyFindingDiscussion.Review review()throws Exception{return StudyFindingDiscussion.assess(root,request,null,false,revision,evidence,catalog);}
    @Test void completeMainAndSupplementDossierRetainsBoundSourcesAndDeclaredUncertainty()throws Exception{
        var result=review();assertEquals("source_bindings_complete_scientific_review_required",result.report().get("status"));assertEquals(8,result.report().get("claim_count"));assertEquals("required",result.report().get("scientific_review"));assertEquals(2,StudyPublicEvidence.list(result.report().get("passages")).size());assertTrue(result.report().get("limitation").toString().contains("do not establish"));var rows=StudyPublicEvidence.list(StudyPublicEvidence.map(StudyPublicEvidence.list(result.report().get("dossiers")).get(0)).get("claims"));assertEquals("inferred",StudyPublicEvidence.map(rows.get(2)).get("epistemic_status"));assertEquals("proposed_not_performed",StudyPublicEvidence.map(rows.get(6)).get("epistemic_status"));
    }
    @Test void sharedPassageCountsOnceAndHasExactSourceOffsets()throws Exception{var r=review();var words=StudyPublicEvidence.map(r.report().get("quoted_words_per_reference"));assertEquals(13,words.get("ref-one"));for(Object raw:StudyPublicEvidence.list(r.report().get("passages"))){var p=StudyPublicEvidence.map(raw);assertEquals(p.get("quote"),Files.readString(source).substring(((Number)p.get("source_start")).intValue(),((Number)p.get("source_end")).intValue()));}}
    @Test void paragraphEditCannotBorrowAnOldClaimBinding()throws Exception{var sections=new ArrayList<Object>(StudyPublicEvidence.list(revision.get("sections")));var main=new LinkedHashMap<>(StudyPublicEvidence.map(sections.get(0)));main.put("text",main.get("text").toString().replace("association is retained","association is discarded"));sections.set(0,main);revision.put("sections",sections);assertThrows(java.io.IOException.class,this::review);}
    @Test void anUncoveredScientificSentenceIsAReviewNeedAndStrictlyBlocks()throws Exception{var sections=new ArrayList<Object>(StudyPublicEvidence.list(revision.get("sections")));var main=new LinkedHashMap<>(StudyPublicEvidence.map(sections.get(0)));main.put("text",main.get("text")+" Unbound extra assertion.");sections.set(0,main);revision.put("sections",sections);assertThrows(java.io.IOException.class,this::review);var p=policy();p.put("mode","review");revision.put("finding_review",p);var r=review();assertEquals("needs_input",r.report().get("status"));assertTrue(r.report().get("needs").toString().contains("outside the claim ledger"));}
    @Test void literalButUncitedSupportIsRejected()throws Exception{
        String token=" [[cite:"+DOI+"]]";
        replaceClaim(1,c->c.put("text",c.get("text").toString().replace(token,"")));
        var sections=new ArrayList<Object>(StudyPublicEvidence.list(revision.get("sections")));
        var supplement=new LinkedHashMap<>(StudyPublicEvidence.map(sections.get(1)));
        supplement.put("text",supplement.get("text").toString().replace("step"+token,"step"));
        sections.set(1,supplement);revision.put("sections",sections);
        assertTrue(assertThrows(java.io.IOException.class,this::review).getMessage().contains("claim-local inline citation"));
    }
    @Test void coveringOnlyTheStartOfAProseTokenDoesNotCoverItsUnboundRemainder()throws Exception{
        replaceClaim(0,c->{String prose=c.get("text").toString();c.put("text",prose.substring(0,prose.length()-3));});
        assertTrue(assertThrows(java.io.IOException.class,this::review).getMessage().contains("outside the claim ledger"));
    }
    @Test void aFabricatedQuoteOrChangedSourceIsRejected()throws Exception{var p=policy();var passages=new ArrayList<Object>(StudyPublicEvidence.list(p.get("passages")));var bad=new LinkedHashMap<>(StudyPublicEvidence.map(passages.get(0)));bad.put("quote","A fabricated experimental result never in the source");passages.set(0,bad);p.put("passages",passages);revision.put("finding_review",p);assertThrows(java.io.IOException.class,this::review);}
    @Test void changedSourceHashIsRejected()throws Exception{Files.writeString(source,Files.readString(source)+"tampered");assertThrows(java.io.IOException.class,this::review);}
    @Test void cyclicMechanismsCannotClaimConsistentEvidence()throws Exception{replaceClaim(0,c->c.put("depends_on",List.of("mechanism")));assertThrows(java.io.IOException.class,this::review);}
    @Test void overlappingClaimsCannotPadCoverage()throws Exception{replaceClaim(7,c->{c.put("paragraph_id","main");c.put("text","synthetic G1 association");});assertThrows(java.io.IOException.class,this::review);}
    @Test void primaryEvidenceCannotBeCertifiedFromAbstractScope()throws Exception{var p=policy();var s=new LinkedHashMap<>(StudyPublicEvidence.map(StudyPublicEvidence.list(p.get("source_texts")).get(0)));s.put("scope","abstract");p.put("source_texts",List.of(s));revision.put("finding_review",p);assertThrows(java.io.IOException.class,this::review);}
    @Test void prosePaddingAndCitationsDoNotReplaceMissingFacets()throws Exception{var d=dossier();d.put("facets",Map.of());var p=policy();p.put("mode","review");p.put("dossiers",List.of(d));revision.put("finding_review",p);var r=review();assertEquals(8,StudyPublicEvidence.list(r.report().get("needs")).size());}
    @Test void observedClaimMustUseItsSameFrozenFindingPrimaryAnalysis()throws Exception{replaceClaim(0,c->c.put("sources",List.of()));assertThrows(java.io.IOException.class,this::review);}
    @Test void concreteNextExperimentNeedsPredictionsAndLimitations()throws Exception{replaceClaim(6,c->c.put("experiment",Map.of("comparison","Perturb a gene")));assertThrows(java.io.IOException.class,this::review);}
    @Test void inheritedSealedCopySurvivesOriginalSourceMutation()throws Exception{var result=review();Path out=Files.createDirectory(root.resolve("first"));result.snapshot(out,revision);Files.writeString(source,"Changed original");Path manifest=out.resolve("metadata/manifest.yaml");Files.writeString(manifest,"synthetic predecessor\n");var inherited=StudyFindingDiscussion.assess(root,request,manifest,true,revision,evidence,catalog);assertEquals("source_bindings_complete_scientific_review_required",inherited.report().get("status"));assertEquals(FollowupSupport.hash(out.resolve("metadata/discussion-sources/paper.txt")),inherited.sources().get(0).sha256());}
    @Test void publicSourceBodiesNeverEnterTheExistingEditorialPayload()throws Exception{review();var export=new LinkedHashMap<String,Object>(revision);var sections=new ArrayList<Object>(StudyPublicEvidence.list(revision.get("sections")));var main=new LinkedHashMap<>(StudyPublicEvidence.map(sections.get(0)));main.remove("discussion_role");sections.set(0,main);export.put("sections",sections);var payload=StudyEditorialReview.payload(export,evidence,Map.of(),catalog);String text=StudyAssistance.json(payload);assertFalse(text.contains("PRIVATE_SOURCE_SENTINEL"));assertFalse(text.contains("public.txt"));assertFalse(payload.containsKey("finding_review"));}
    @Test void legacyDraftsArePreservedWithExplicitMissingDossierNeeds()throws Exception{revision.remove("finding_review");var r=review();assertEquals("needs_input",r.report().get("status"));assertTrue(r.report().get("needs").toString().contains("supply a source-grounded"));assertEquals(2,StudyPublicEvidence.list(revision.get("sections")).size());}
    @Test void disablingTheLocalReviewRequiresAnExplicitReason()throws Exception{revision.put("finding_review",Map.of("mode","off"));assertThrows(java.io.IOException.class,this::review);revision.put("finding_review",Map.of("mode","off","rationale","Preserve this incomplete legacy draft for review"));assertEquals("omitted_by_explicit_request",review().report().get("status"));}
    @Test void resultChangesCannotSilentlyReuseAnOldInterpretationEvenWithUnchangedProse()throws Exception{Path inventory=root.resolve("inventory");Files.writeString(inventory.resolve("finding-inventory.jsonl"),Files.readString(inventory.resolve("finding-inventory.jsonl")).replace("\"G1\"","\"G1\",\"updated_effect\":-1"));StudyTestSources.seal(inventory,"finding_inventory","inventory","H");assertThrows(java.io.IOException.class,this::review);var p=policy();p.put("mode","review");revision.put("finding_review",p);assertTrue(review().report().get("needs").toString().contains("current frozen finding_inventory_sha256"));}
}
